with latest as (select * from employees qualify row_number() over (partition by level, dept_id order by hire_date nulls first, id) = 1) select job_title, case when salary >= 145000 then 'PREMIUM' else 'STANDARD' end as salary_tier, count(case when job_title = 'Intern' then 1 end) as intern_count, count(case when job_title = 'Engineer' then 1 end) as engineer_count, count(case when job_title = 'Director' then 1 end) as director_count from latest group by grouping sets ((job_title, case when salary >= 145000 then 'PREMIUM' else 'STANDARD' end), (job_title)) having count(case when job_title = 'Engineer' then 1 end) < 1000 order by job_title desc nulls last;
